//! Slack's standard emoji names, which are not the app's: `female-office-worker`,
//! with a skin tone written as a second code, `:+1::skin-tone-3:`. Text turns
//! into the glyphs; a reaction goes by the app's own shortcode for the same
//! glyph, and back to Slack's name when sent. A name Slack does not list (a
//! custom emoji) goes through unchanged. Generated by
//! `scripts/generate-slack-emojis.mjs` from emoji-datasource.

use std::collections::HashMap;
use std::sync::OnceLock;

const TABLE: &str = include_str!("../data/slack-emojis.tsv");
const TONE: &str = "::skin-tone-";

struct Slack {
    /// Name to its glyph, then its five skin-tone glyphs when it takes them.
    by_name: HashMap<&'static str, (String, Option<[String; 5]>)>,
    /// Glyph to Slack's first name for it, with the tone (2 to 6) it carries.
    by_glyph: HashMap<String, (&'static str, Option<u8>)>,
}

fn glyph(points: &str) -> String {
    points.split('-').filter_map(|p| u32::from_str_radix(p, 16).ok().and_then(char::from_u32)).collect()
}

fn bare(glyph: &str) -> String {
    glyph.replace('\u{FE0F}', "")
}

fn slack() -> &'static Slack {
    static SLACK: OnceLock<Slack> = OnceLock::new();
    SLACK.get_or_init(|| {
        let (mut by_name, mut by_glyph) = (HashMap::new(), HashMap::new());
        for line in TABLE.lines() {
            let mut fields = line.split('\t');
            let (Some(name), Some(points), Some(tones)) = (fields.next(), fields.next(), fields.next()) else {
                continue;
            };
            let base = glyph(points);
            let toned: Option<[String; 5]> =
                (tones != "-").then(|| tones.split(',').map(glyph).collect::<Vec<_>>().try_into().ok()).flatten();
            by_glyph.entry(bare(&base)).or_insert((name, None));
            for (i, g) in toned.iter().flatten().enumerate() {
                by_glyph.entry(bare(g)).or_insert((name, Some(i as u8 + 2)));
            }
            by_name.insert(name, (base, toned));
        }
        Slack { by_name, by_glyph }
    })
}

/// A Slack emoji (`name`, or `name::skin-tone-N` as reactions write it) to its glyph.
pub fn glyph_of(code: &str) -> Option<String> {
    let code = code.trim_matches(':');
    let (name, tone) = match code.split_once(TONE) {
        Some((name, tone)) => (name, tone.parse::<usize>().ok().filter(|t| (2..=6).contains(t))),
        None => (code, None),
    };
    let (base, toned) = slack().by_name.get(name)?;
    Some(match (tone, toned) {
        (Some(t), Some(toned)) => toned[t - 2].clone(),
        _ => base.clone(),
    })
}

/// `:name:` and `:name::skin-tone-N:` into their glyphs; any other `:word:`
/// (a custom emoji, an unknown name) stays.
pub fn replace(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut rest = text;
    while let Some(open) = rest.find(':') {
        let after = &rest[open + 1..];
        let name_end = after
            .find(|c: char| !(c.is_ascii_alphanumeric() || matches!(c, '_' | '-' | '+' | '\'')))
            .unwrap_or(after.len());
        let closed = name_end > 0 && after[name_end..].starts_with(':');
        let found = closed.then(|| &after[..name_end]).and_then(|name| {
            let tail = &after[name_end + 1..];
            let tone = tail
                .strip_prefix(":skin-tone-")
                .and_then(|t| t.get(..2))
                .filter(|t| t.as_bytes()[1] == b':' && (b'2'..=b'6').contains(&t.as_bytes()[0]))
                .map(|t| &t[..1]);
            let code = match tone {
                Some(t) => format!("{name}{TONE}{t}"),
                None => name.to_owned(),
            };
            let consumed = 1 + name_end + 1 + tone.map_or(0, |_| ":skin-tone-N:".len());
            glyph_of(&code).map(|g| (g, consumed))
        });
        match found {
            Some((g, consumed)) => {
                out.push_str(&rest[..open]);
                out.push_str(&g);
                rest = &rest[open + consumed..];
            }
            None => {
                out.push_str(&rest[..=open]);
                rest = after;
            }
        }
    }
    out.push_str(rest);
    out
}

/// A Slack reaction name as the app's reaction code: its own shortcode for
/// the same glyph, else the name itself (a custom emoji).
pub fn reaction_code(name: &str) -> String {
    glyph_of(name).and_then(|g| rv_provider::emoji::shortcode(&g)).map_or_else(|| name.to_owned(), str::to_owned)
}

/// The app's reaction code as Slack's name (`name` or `name::skin-tone-N`),
/// else the code itself (a custom emoji, or already a Slack name).
pub fn slack_name(code: &str) -> String {
    let code = code.trim_matches(':');
    if slack().by_name.contains_key(code) {
        return code.to_owned();
    }
    let found = rv_provider::emoji::unicode(code).and_then(|g| slack().by_glyph.get(&bare(g)));
    match found {
        Some((name, Some(tone))) => format!("{name}{TONE}{tone}"),
        Some((name, None)) => (*name).to_owned(),
        None => code.to_owned(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn text_names_and_skin_tones_become_glyphs() {
        assert_eq!(
            replace(":man-wearing-turban::skin-tone-6::female-office-worker: hi :issou: :+1:"),
            "\u{1F473}\u{1F3FF}\u{200D}\u{2642}\u{FE0F}\u{1F469}\u{200D}\u{1F4BC} hi :issou: \u{1F44D}"
        );
        assert_eq!(replace("time 12:30:45 and :not a code:"), "time 12:30:45 and :not a code:");
        assert_eq!(replace(":baby::skin-tone-9:"), "\u{1F476}:skin-tone-9:");
    }

    #[test]
    fn reactions_go_both_ways_through_the_app_codes() {
        let thumbs = reaction_code("+1");
        assert_eq!(rv_provider::emoji::unicode(&thumbs), Some("\u{1F44D}"), "{thumbs}");
        assert_eq!(glyph_of(&slack_name(&thumbs)).as_deref(), Some("\u{1F44D}"), "back to a Slack name of 👍");
        let toned = reaction_code("+1::skin-tone-3");
        assert_eq!(rv_provider::emoji::unicode(&toned), Some("\u{1F44D}\u{1F3FC}"));
        assert_eq!(glyph_of(&slack_name(&toned)).as_deref(), Some("\u{1F44D}\u{1F3FC}"));
        assert!(slack_name(&toned).ends_with("::skin-tone-3"));
        assert_eq!(reaction_code("issou"), "issou");
        assert_eq!(slack_name("issou"), "issou");
        assert_eq!(slack_name(":female-office-worker:"), "female-office-worker");
    }
}
